import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { person, shortDate, t, userUrl } from '../api';
/** The Reports tab (moderators): letters their recipients chose to show you, and only those. */
export default class Reports extends Component {
  reports = null;
  oninit(vnode) {
    super.oninit(vnode);
    app.store.find('slow-mail-reports').then(list => this.reports = list).catch(() => this.reports = []).finally(() => m.redraw());
  }
  view() {
    if (this.reports === null) return m(LoadingIndicator, null);
    if (!this.reports.length) return m("p", {
      className: "SlowMailPals-none"
    }, t('reports.none'));
    return m("div", {
      className: "SlowMailReports"
    }, m("p", {
      className: "helpText"
    }, t('reports.intro')), this.reports.map(report => this.row(report)));
  }
  row(report) {
    const reporter = person(report.reporter());
    const sender = person(report.sender());
    return m("div", {
      className: "SlowMailReportRow"
    }, m("div", {
      className: "SlowMailReportRow-head"
    }, m("span", null, t('reports.line', {
      reporter: reporter?.displayName || t('envelope.someone'),
      sender: sender?.displayName || t('envelope.someone'),
      date: shortDate(report.reportedAt())
    })), sender ? m(Link, {
      className: "Button Button--flat",
      href: userUrl(sender)
    }, t('reports.sender_profile')) : null, m(Button, {
      className: "Button",
      icon: "fas fa-check",
      onclick: () => this.resolve(report)
    }, t('reports.resolve'))), report.reason() ? m("p", {
      className: "SlowMailReportRow-reason"
    }, report.reason()) : null, m("div", {
      className: "SlowMailLetter-paper SlowMailReportRow-letter"
    }, m("div", {
      className: "SlowMailLetter-body"
    }, report.body() ?? t('letter.unreadable'))));
  }
  resolve(report) {
    report.save({
      resolved: true
    }).then(() => {
      this.reports = (this.reports || []).filter(r => r !== report);
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-slow-mail', 'forum/components/Reports', Reports);