/** The part of the `flarum` global this extension reads: core's module registry, for its lazy chunks. */

const registry = () => globalThis.flarum.reg;
function defaultExport(mod) {
  const record = mod;
  return record?.default ?? mod;
}

/** Core components the page builds on, loaded through the registry: they live in core's lazy chunks. */
export let PageStructure;
export let IndexSidebar;
export async function loadCore() {
  if (PageStructure && IndexSidebar) return;
  const [structure, sidebar] = await Promise.all([registry().asyncModuleImport('flarum/forum/components/PageStructure'), registry().asyncModuleImport('flarum/forum/components/IndexSidebar')]);
  PageStructure = defaultExport(structure);
  IndexSidebar = defaultExport(sidebar);
}
export const logInModal = () => registry().asyncModuleImport('flarum/forum/components/LogInModal').then(m => defaultExport(m));